          </div>
          <div class="overflow-x-auto">
            <table class="w-full border-collapse">
              <thead>
                <tr class="bg-gray-100">
                  <th class="p-3 text-right text-[#4D4D4D] text-sm font-light">{{ $t('reports.time') }}</th>
                  <th class="p-3 text-right text-[#4D4D4D] text-sm font-light">{{ $t('reports.method') }}</th>
                  <th class="p-3 text-right text-[#4D4D4D] text-sm font-light">{{ $t('reports.statusCode') }}</th>
