</template>

<script>
import axios from 'axios'
import LoadingSpinner from '../LoadingSpinner.vue'

export default {
  name: 'ErrorReports',
  components: {
    LoadingSpinner
  },
  data() {
    return {
      currentTab: 'send/live',
      receivedMessages: [],
      sentMessages: [],
      errorLogs: [],
      currentPage: 1,
      pageSize: 20,
      loading: true,
      error: null,
      tabs: [
        { id: 'send/live', name: 'پیام‌های ارسالی' },
        { id: 'receive/live', name: 'پیام‌های دریافتی' },
        { id: 'errors', name: 'گزارش خطاها' }
      ]
    }
  },
  methods: {
    switchTab(tabId) {
      this.currentTab = tabId;
      this.currentPage = 1;
      this.updateUrl();
      this.fetchData(1);
    },
    updateUrl() {
      const url = new URL(window.location.href);
      url.searchParams.set('section', this.currentTab);
      window.history.pushState({}, '', url);
    },
    getTabFromUrl() {
      const url = new URL(window.location.href);
      const section = url.searchParams.get('section');
      return this.tabs.find(t => t.id === section) ? section : 'send/live';
    },
    async fetchData(page = 1) {
      this.loading = true;
      this.error = null;
      
      try {
        if (this.currentTab === 'errors') {
          console.log('Fetching error logs...');
          const response = await axios.post(ajaxurl, new URLSearchParams({
            action: 'sms_ir_get_error_logs',
            page: page,
            per_page: this.pageSize
          }));

          console.log('Error logs response:', response.data);
          
          if (response.data.success) {
            this.errorLogs = response.data.data.logs || [];
            console.log('Logs loaded:', this.errorLogs);
            console.log('Total logs:', this.errorLogs.length);
          } else {
            this.error = response.data.data || this.$t('error.fetchFailed');
            console.error('Failed to fetch logs:', this.error);
          }
        } else {
          const params = new URLSearchParams({
            action: "sms_ir_get_messages",
            type: this.currentTab,
            page: page,
            pageSize: this.pageSize
          });

          const response = await axios.get(
            `${window.sms_ir_login.ajaxUrl}?${params.toString()}`
          );

          if (response.data.success) {
            if (this.currentTab === 'receive/live') {
              this.receivedMessages = response.data.data;
            } else {
              this.sentMessages = response.data.data;
            }
            this.currentPage = page;
          } else {
            this.error = response.data.data || this.$t('error.fetchFailed');
          }
        }
      } catch (err) {
        console.error('Error in fetchData:', err);
        this.error = err.response?.data?.message || this.$t('error.fetchFailed');
      } finally {
        this.loading = false;
      }
    },
    async clearLogs() {
      try {
        this.loading = true;
        const response = await axios.post(ajaxurl, new URLSearchParams({
          action: 'sms_ir_clear_error_logs',
        }));

        if (response.data.success) {
          this.errorLogs = [];
          this.$toast.success(this.$t('reports.logsCleared'));
        } else {
          this.$toast.error(this.$t('error.clearFailed'));
        }
      } catch (err) {
        console.error('Error clearing logs:', err);
        this.$toast.error(err.response?.data?.message || this.$t('error.clearFailed'));
      } finally {
        this.loading = false;
      }
    },
    formatNumber(num) {
      if (num === null || num === undefined) return "0";
      if (typeof num === 'number' && !Number.isInteger(num)) {
        num = Math.floor(num);
      }
      return num.toLocaleString("fa-IR");
    },
    getDeliveryStatus(state) {
      const states = {
        1: this.$t('reports.deliveryStatus.deliveredToPhone'),      // رسیده به گوشی
        2: this.$t('reports.deliveryStatus.notDeliveredToPhone'),   // نرسیده به گوشی
        3: this.$t('reports.deliveryStatus.processingByTelecom'),   // پردازش در مخابرات
        4: this.$t('reports.deliveryStatus.notDeliveredToTelecom'), // نرسیده به مخابرات
        5: this.$t('reports.deliveryStatus.deliveredToTelecom'),    // رسیده به مخابرات
        6: this.$t('reports.deliveryStatus.error'),                 // خطا
        7: this.$t('reports.deliveryStatus.blacklist')              // لیست سیاه
      }
      return states[state] || this.$t('reports.deliveryStatus.error')
    },
    formatDate(timestamp) {
      if (!timestamp) return '';
      // Convert Unix timestamp to milliseconds for JavaScript Date
      const date = new Date(timestamp * 1000);
      return date.toLocaleString('fa-IR', {
        year: 'numeric',
        month: '2-digit',
        day: '2-digit',
        hour: '2-digit',
        minute: '2-digit',
        second: '2-digit',
        hour12: false
      });
    },
    getMethod(context) {
      if (!context || typeof context !== 'object') return '';
      return context.endpoint || '';
    },
    getStatusCode(context) {
      if (!context || typeof context !== 'object') return '';
      if (context.response && context.response.status) {
        return context.response.status;
      }
      return '';
    },
  getContextMessage(context) {
  if (!context || typeof context !== 'object') return '';
    
  if (context.response) {
    if (context.response.error) {
      return context.response.error;
    }
  }
  if (context.error) {
      return context.error;
    }

  return JSON.stringify(context, null, 2);
}
  },
  mounted() {
    // Set initial tab from URL
    this.currentTab = this.getTabFromUrl();
    this.fetchData();
  }
};
</script>

