import ContactsTab from "./tabs/ContactsTab.vue";

export default {
  components: {
    GeneralSettings,
    LoginSettings,
    ShortCodes,
    TemplateManager,
    ErrorReports,
    NewsletterManager,
    GravityFormsSettings,
    WooCommerceSettings,
    LeaveCartSettings,
    ExcelUpload,
    NotifyMeSettings,
    ContactsTab,
  },
  data() {
    return {
      readOnly: [
        "shortcode",
        "template",
        "reports",
        "forms",
        "woocommerce",
        "newsletter",
        "leavecart",
        "excelupload",
        "contacts"
            ],
      sms_ir_login: window.sms_ir_login || "",
      currentTab: "general",
      selectedTab: "general",
      currentSub: 1,
      buyed_product: {},
      defaultSettings: {
        settings: {
          general: {
            api_key: '',
