            show_logo: true,
            show_copyright: true,
            logo_url: '',
            enable_otp: false,
            otp_length: 5,
            otp_expiry: 90
          },
          login_style: {
            modal_button_text: '',
            modal_button_bg: '#FFBF00',
            modal_button_text_color: '#0D0D0D',
            modal_background: '#FFFFFF',
            form_background: '#FFFFFF',
            primary_button_bg: '#FFBF00',
            primary_button_text_color: '#0D0D0D'
          },
          newsletter: {
            is_active: false,
            template_id: '',
            message: '',
            logo_url: '',
            enable_double_optin: false
          },
          forms: {
            is_active: false,
            template_id: '',
            message: '',
            logo_url: ''
          },
          woocommerce: {
            is_active: false,
            change_checkout: false,
            notifications: []
          },
          notifyme: {
            is_active: false,
            template_id: '',
            button_text: '',
            notification_text: '',
            enable_button: true,
            button_style: 'default'
          }
        }
      },
      checkedSettings: {
        settings: {
          general: {
            api_key: '',
            secret_key: '',
            line_number: '',
            is_active: true,
            enable_credit_notification: false,
            credit_threshold: 100
          },
          login: {
            is_active: false,
            change_admin:false,
            template_id: '',
            message: '',
            show_logo: true,
            show_copyright: true,
            logo_url: '',
            enable_otp: false,
            otp_length: 5,
            otp_expiry: 90
          },
          login_style: {
            modal_button_text: '',
            modal_button_bg: '#FFBF00',
            modal_button_text_color: '#0D0D0D',
            modal_background: '#FFFFFF',
            form_background: '#FFFFFF',
            primary_button_bg: '#FFBF00',
            primary_button_text_color: '#0D0D0D'
          },
          newsletter: {
            is_active: false,
            template_id: '',
            message: '',
            logo_url: '',
            enable_double_optin: false
          },
          forms: {
            is_active: false,
            template_id: '',
            message: '',
            logo_url: ''
          },
          woocommerce: {
            is_active: false,
            change_checkout: false,
            notifications: []
          },
          notifyme: {
            is_active: false,
            template_id: '',
            button_text: '',
            notification_text: '',
            enable_button: true,
            button_style: 'default'
          }
        }
      },
      show: true,
      warning: false,
      saving: false,
      accountStats: null,
      accountStatsError: null,
      accountStatsLoading: true,
      logoSrc:
        window.sms_ir_login?.pluginUrl +
        "/img/logo.svg",
    };
  },
  mounted() {
    this.selectTabFromQuery();
    window.addEventListener(
      "popstate",
      this.selectTabFromQuery
    );
    
    // Wait for WordPress core to be fully loaded
    if (typeof wp === 'undefined') {
      const checkWpLoaded = setInterval(() => {
        if (typeof wp !== 'undefined' && wp.hooks) {
          clearInterval(checkWpLoaded);
          this.initializeAfterWpLoaded();
        }
      }, 100);
    } else {
      this.initializeAfterWpLoaded();
    }
  },
  methods: {
    initializeAfterWpLoaded() {
      this.fetchAccountStats();
      this.initializeSettings();
    },
    selectTabFromQuery() {
      const url = new URL(window.location.href);
      const tab = url.searchParams.get("tab");
      if (tab) {
        this.currentTab = tab;
      }
    },
    async initializeSettings() {
      try {
        const response = await axios.post(
          `${this.sms_ir_login.ajaxUrl}`,
          {
            nonce: `${this.sms_ir_login.nonce}`,
            action: "sms_ir_get_settings",
          },
          {
            headers: {
              "Content-Type": "application/x-www-form-urlencoded",
            },
            withCredentials: true,
          }
        );

        if (response.data && response.data.settings) {
          this.checkedSettings = {
            settings: this.mergeSettings(this.defaultSettings.settings, response.data.settings)
          };
        } else {
          await this.saveDefaultSettings();
        }
      } catch (error) {
        console.error("Error initializing settings:", error);
        await this.saveDefaultSettings();
      }
    },

    mergeSettings(defaults, existing) {
      const merged = { ...defaults };
      
      Object.keys(existing).forEach(key => {
        if (typeof existing[key] === 'object' && !Array.isArray(existing[key])) {
          merged[key] = this.mergeSettings(defaults[key] || {}, existing[key]);
        } else {
          merged[key] = existing[key];
        }
      });
      
      return merged;
    },

    async saveDefaultSettings() {
      try {
        const data = {
          nonce: this.sms_ir_login.nonce,
          action: "sms_ir_save_settings",
          settings: this.defaultSettings.settings
        };

        const response = await axios.post(
          `${this.sms_ir_login.ajaxUrl}`,
          data,
          {
            headers: {
              "Content-Type": "application/x-www-form-urlencoded",
            },
            withCredentials: true,
          }
        );

        if (response.data.success) {
          this.checkedSettings = {
            settings: this.defaultSettings.settings
          };
        } else {
          this.checkedSettings = {
            settings: this.defaultSettings.settings
          };
        }
      } catch (error) {
        console.error("Error saving default settings:", error);
        this.checkedSettings = {
          settings: this.defaultSettings.settings
        };
      }
    },
    handleTabClick(index, sub = 1) {
      this.currentTab = index;
      this.currentSub = sub;
      this.show = true;
      this.redirect = false;
      const url = new URL(window.location.href);
      url.searchParams.set("tab", index);
      window.history.pushState({}, "", url);
    },
    async saveSettings() {
      try {
        this.saving = true;
        this.checkedSettings;
        let data = this.checkedSettings;
        data.nonce = this.sms_ir_login.nonce;
        data.action = "sms_ir_save_settings";
        const response = await axios.post(
          `${this.sms_ir_login.ajaxUrl}`,
          data,
          {
            headers: {
              "Content-Type":
                "application/x-www-form-urlencoded",
            },
            withCredentials: true,
          }
        );
        if (response.data.setting) {
          this.checkedSettings =
            response.data.setting;
        }
        if (response.data.success) {
          this.saving = false;
          Swal.fire({
            text:
              response.data.message ||
              this.$t(
                "SettingsSavedSuccessfully"
              ),
            icon: "success",
            toast: true,
            position: "top-start",
            showConfirmButton: false,
            timer: 3000,
            timerProgressBar: true,
            customClass: {
              popup: "smsir-swal",
            },
          });
        }
      } catch (error) {
        this.saving = false;
        let errorMessage = this.$t(
          "SettingsSaveError"
        );

        if (
          error.response &&
          error.response.data &&
          error.response.data.message
        ) {
          errorMessage =
            error.response.data.message;
        }

        Swal.fire({
          text: errorMessage,
          icon: "error",
          toast: true,
          position: "top-start",
          showConfirmButton: false,
          timer: 3000,
          timerProgressBar: true,
          customClass: {
            popup: "smsir-swal",
          },
        });
        console.error(
          "Error saving settings:",
          error
        );
      }
    },
    async fetchAccountStats() {
      try {
        this.accountStatsLoading = true;
        const response = await axios.post(
          window.sms_ir_login.ajaxUrl,
          new URLSearchParams({
            action: "sms_ir_get_account_stats",
            nonce: window.sms_ir_login.nonce,
            type: "all",
          }),
          {
            headers: {
              "Content-Type":
                "application/x-www-form-urlencoded",
            },
          }
        );
        
        if (response.data && response.data.success) {
          this.accountStats = response.data.data || {
            active_lines: 0,
            credit: 0,
            today_sent: 0,
            today_received: 0
          };
        } else {
          this.accountStats = {
            active_lines: 0,
            credit: 0,
            today_sent: 0,
            today_received: 0
          };
        }
      } catch (error) {
        console.error("Error fetching account stats:", error);
        this.accountStatsError = error.response?.data?.message || "Failed to fetch account stats";
        this.accountStats = {
          active_lines: 0,
          credit: 0,
          today_sent: 0,
          today_received: 0
        };
      } finally {
        this.accountStatsLoading = false;
      }
    },
    formatNumber(num) {
      if (num === null || num === undefined)
        return "0";
      if (
        typeof num === "number" &&
        !Number.isInteger(num)
      ) {
        num = Math.floor(num);
      }
      return num.toLocaleString("fa-IR");
    },
    handleDisconnectedClick() {
      Swal.fire({
        title: this.$t('recheckConnection'),
        text: this.$t('recheckConnectionDescription'),
        icon: 'info',
        showConfirmButton: false,
        timer: 5000,
        timerProgressBar: true,
        customClass: {
          popup: 'smsir-swal',
          title: 'text-[18px] text-[#0D0D0D]',
          content: 'text-[#4D4D4D]',
          timerProgressBar: 'bg-[#12BA6C]'
        },
        didOpen: () => {
          Swal.showLoading();
        }
      }).then(() => {
        window.location.reload();
      });
    },
  },
  computed: {
    isWooCommerceActive() {
      return window.sms_ir_login?.woocommerce_active === true;
    },
  },
};
</script>
